// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Scenario: user deposits exactly MinSum (1 ether) via Put, then tries Collect immediately
        address user = address(0x1234);
        uint256 depositAmount = 1 ether;

        // Give user ether and deposit via Put (unlockTime set to block.timestamp + 100)
        vm.deal(user, depositAmount);
        vm.prank(user);
        c.Put{value: depositAmount}(block.timestamp + 100);

        // Attempt Collect before unlock — reference requires MinSum check, bug doesn't
        // Both check balance >= amount and time > unlockTime; reference additionally requires balance >= MinSum
        // Since balance == MinSum == 1 ether, reference rejects (balance >= MinSum true, but time condition fails)
        // Bug accepts (balance >= amount true, time fails — actually fails too? Wait, time not passed -> fails)
        // Need time after unlock: warp forward so both pass time but bug passes because no MinSum, reference may still? Let's re-analyze.

        // Actually: the difference is MinSum check. After deposit, balance = 1 ether = MinSum. Reference if(acc.balance>=MinSum && acc.balance>=_am && block.timestamp>acc.unlockTime)
        // Bug if(acc.balance>=_am && block.timestamp>acc.unlockTime). So bug removes MinSum condition. 
        // To make reference fail and bug succeed, need: balance >= _am true, time > unlockTime true, but balance >= MinSum false. That means balance < MinSum.
        // So deposit less than MinSum, then Collect after unlock. Reference fails, bug succeeds.
        // Let's deposit 0.5 ether = 0.5e18, MinSum = 1e18, so balance < MinSum.
        uint256 smallDeposit = 0.5 ether;
        vm.deal(user, smallDeposit);
        vm.prank(user);
        c.Put{value: smallDeposit}(block.timestamp + 100);

        // Warp past unlock
        vm.warp(block.timestamp + 200);

        // Now Collect smallDeposit (0.5 ether)
        bool ok;
        try c.Collect(smallDeposit) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference: ok == false (balance < MinSum), Bug: ok == true
        // Assert that reference holds: assertTrue(!ok), which will fail on bug
        assertTrue(!ok);
    }
}

