pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Scenario: user deposits 1 ether, then warp past unlock time
        // Reference requires block.timestamp > acc.unlockTime; mutant does not
        address user = address(0x1234);
        uint deposit = 1 ether;
        uint collectAmt = 1 ether;

        vm.deal(user, deposit);
        vm.prank(user);
        c.Put{value: deposit}(block.timestamp + 100); // unlockTime = block.timestamp + 100

        // Warp past the unlock time
        vm.warp(block.timestamp + 200);

        // Now call Collect – reference should succeed, mutant also succeeds but diverges later
        // Actually: both succeed because time check is satisfied
        // But the property says P.Collect() != M.Collect() meaning return value differs?
        // The condition change removes time check; to diverge we need a case where time check FAILS
        // So warp BEFORE unlock time
        vm.warp(block.timestamp - 150); // reset or better: start with warp
        // Redo: we need to set up so reference reverts, mutant succeeds
        // New scenario: deposit, warp to before unlock, then Collect
        // Actually we cannot warp back. Let's do:
        // Deploy fresh, deposit at time T with unlock T+100
        // Then warp to T+50 (before unlock)
        // Reference: Collect reverts because block.timestamp <= unlockTime
        // Mutant: Collect succeeds (removed time check)

        // Let's code properly:
        // Start at time 1000
        vm.warp(1000);
        vm.deal(user, deposit);
        vm.prank(user);
        c.Put{value: deposit}(1100); // unlockTime = 1100

        vm.warp(1050); // before unlock

        bool refSucceeded;
        try c.Collect(collectAmt) {
            refSucceeded = true;
        } catch {
            refSucceeded = false;
        }

        // Assert that reference reverts (refSucceeded false) and mutant would succeed
        // But we only have one contract instance. So we need to test the reference behavior.
        // Since the test runs on the deployed contract (which is the reference),
        // we assert that refSucceeded is false (the reference reverts).
        // To check mutant would succeed, we could note that the mutant's condition is weaker,
        // but we can't deploy mutant in this test. The property is that reference and mutant differ.
        // Since we are testing on reference, we assert its behavior.
        // The assertion: the reference's balance remains unchanged because Collect reverted
        // The mutant would have transferred, so balance would differ.
        // We can check c.Acc(user).balance after the attempt.
        // Actually we just need one assert that reference holds and mutant would break.
        // The simplest: check that c.Collect returns false (revert) while mutant would not revert.
        // We assert refSucceeded == false.
        assertTrue(!refSucceeded);
    }
}

