pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // User deposits exactly 1 wei, unlockTime set to 0 (current block.timestamp)
        vm.deal(address(0x123), 1 wei);
        vm.prank(address(0x123));
        c.Put{value: 1 wei}(0);

        // Warp past unlockTime to ensure time check passes (block.timestamp > 0)
        vm.warp(1);

        // Attempt Collect(1 wei) from the same user
        vm.prank(address(0x123));
        (bool success, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", 1 wei));

        // Reference: time check passes, MinSum = 1 ether > 1 wei, so Collect reverts => success = false
        // Buggy: time check removed, but condition acc.balance >= MinSum fails (1 wei < 1 ether), so also reverts => success = false
        // To force divergence, we need a case where reference succeeds and buggy fails. We'll use a deposit >= MinSum and time check that reference passes.
        // Reset by deploying new contract
        c = new C(address(this));

        // Now: User deposits 1 ether with unlockTime = 0
        vm.deal(address(0x456), 1 ether);
        vm.prank(address(0x456));
        c.Put{value: 1 ether}(0);

        // Warp past unlockTime (already 0, but warp to 1)
        vm.warp(1);

        // Collect(1 ether) - both conditions satisfied: balance >= MinSum, balance >= 1 ether, time past
        vm.prank(address(0x456));
        (bool success2, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", 1 ether));

        // Reference: time check passes => Collect succeeds => success2 = true, balance becomes 0
        // Buggy: time check removed but same conditions => also succeeds => both succeed. No divergence.

        // We need the exact divergence: reference succeeds, buggy fails. 
        // Use case where time check is the differentiator: deposit 1 ether, set unlockTime far future, then Collect before unlockTime.
        // Reset
        c = new C(address(this));

        // User deposits 1 ether with unlockTime = 2 (future)
        vm.deal(address(0x789), 1 ether);
        vm.prank(address(0x789));
        c.Put{value: 1 ether}(2);

        // Warp to time 1 (before unlockTime)
        vm.warp(1);

        // Try Collect(1 wei) - reference: time check fails => revert => success3 = false
        // Buggy: no time check => condition balance >= MinSum (1 ether >= 1 ether) and balance >= 1 wei => true => success3 = true
        vm.prank(address(0x789));
        (bool success3, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", 1 wei));

        // Reference: false (revert), buggy: true (success)
        // Assert that the call succeeded, which is false for reference and true for buggy
        assertTrue(success3 == true, "Buggy should allow Collect but reference rejects");
    }
}

