contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Setup: userA deposits exactly MinSum (1 ether) and sets unlockTime = now
        address userA = address(0xAAAA);
        address userB = address(0xBBBB);
        vm.deal(userA, 1 ether);
        vm.prank(userA);
        c.Put{value: 1 ether}(block.timestamp);  // unlockTime = block.timestamp

        // userB (no balance) tries to Collect(1 ether) — reference should revert (time check not passed on userB's account)
        bool ok;
        vm.prank(userB);
        try c.Collect(1 ether) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference C: userB has balance=0, unlockTime=0, so time check fails => revert => ok=false
        // Buggy M: removes time check, only checks balance>=MinSum && balance>=_am => both false => revert => ok=false
        // This diverges? Check balance after: in reference userB stays 0, in buggy also stays 0 — wait need actual divergence.
        // Let's adjust: userA deposits, then userB deposits exactly MinSum after warp, then call Collect before time.
        vm.deal(userB, 1 ether);
        vm.prank(userB);
        c.Put{value: 1 ether}(block.timestamp + 100);  // unlockTime far future
        // Now userB has 1 ether but unlockTime in future
        vm.prank(userB);
        try c.Collect(1 ether) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: balance>=MinSum (1>=1), balance>=1, but time > unlockTime? No => revert => ok=false
        // Buggy: balance>=MinSum (1>=1), balance>=1, no time check => succeeds => ok=true
        // So we assert that ok is false (reference behavior). Buggy would return true
        assertTrue(!ok, "FAIL: reference should revert on time-locked Collect");
    }
}

